--
-- Name: vw_jeferson_assinaturas_resumo; Type: VIEW; Schema: biblioteca_jogos; Owner: neondb_owner
--

CREATE VIEW biblioteca_jogos.vw_jeferson_assinaturas_resumo AS
 SELECT plano,
    count(*) AS total_assinantes,
    count(*) FILTER (WHERE (data_expiracao >= CURRENT_DATE)) AS assinaturas_ativas,
    ( SELECT round(avg(a.nota), 2) AS round
           FROM biblioteca_jogos.avaliacoes a
          WHERE (a.id_usuario IN ( SELECT ass2.id_usuario
                   FROM biblioteca_jogos.assinaturas ass2
                  WHERE ((ass2.plano)::text = (ass.plano)::text)))) AS media_nota_avaliacoes_do_plano
   FROM biblioteca_jogos.assinaturas ass
  GROUP BY plano
  ORDER BY (count(*)) DESC;


ALTER VIEW biblioteca_jogos.vw_jeferson_assinaturas_resumo OWNER TO neondb_owner;

--
-- Name: vw_jeferson_desenvolvedoras_desempenho; Type: MATERIALIZED VIEW; Schema: biblioteca_jogos; Owner: neondb_owner
--

CREATE MATERIALIZED VIEW biblioteca_jogos.vw_jeferson_desenvolvedoras_desempenho AS
 SELECT d.id_desenvolvedora,
    d.nome AS desenvolvedora,
    d.pais_origem,
    count(j.id_jogo) AS total_jogos,
    round(avg(j.preco), 2) AS preco_medio,
    ( SELECT round(avg(a.nota), 2) AS round
           FROM (biblioteca_jogos.avaliacoes a
             JOIN biblioteca_jogos.jogos j2 ON ((j2.id_jogo = a.id_jogo)))
          WHERE (j2.id_desenvolvedora = d.id_desenvolvedora)) AS media_nota_geral
   FROM (biblioteca_jogos.desenvolvedoras d
     LEFT JOIN biblioteca_jogos.jogos j ON ((j.id_desenvolvedora = d.id_desenvolvedora)))
  GROUP BY d.id_desenvolvedora, d.nome, d.pais_origem
  ORDER BY (count(j.id_jogo)) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW biblioteca_jogos.vw_jeferson_desenvolvedoras_desempenho OWNER TO neondb_owner;

--
-- Name: vw_jeferson_horas_por_plataforma; Type: VIEW; Schema: biblioteca_jogos; Owner: neondb_owner
--

CREATE VIEW biblioteca_jogos.vw_jeferson_horas_por_plataforma AS
 SELECT p.id_plataforma,
    p.nome AS plataforma,
    count(DISTINCT jp.id_jogo) AS total_jogos,
    COALESCE(sum(b.horas_jogadas), (0)::numeric) AS total_horas_jogadas,
    round(avg(b.horas_jogadas), 2) AS media_horas_por_registro
   FROM ((biblioteca_jogos.plataformas p
     JOIN biblioteca_jogos.jogos_plataformas jp ON ((jp.id_plataforma = p.id_plataforma)))
     LEFT JOIN biblioteca_jogos.biblioteca b ON ((b.id_jogo = jp.id_jogo)))
  GROUP BY p.id_plataforma, p.nome
  ORDER BY COALESCE(sum(b.horas_jogadas), (0)::numeric) DESC;


ALTER VIEW biblioteca_jogos.vw_jeferson_horas_por_plataforma OWNER TO neondb_owner;

--
-- Name: vw_jeferson_jogos_bem_avaliados; Type: VIEW; Schema: biblioteca_jogos; Owner: neondb_owner
--

CREATE VIEW biblioteca_jogos.vw_jeferson_jogos_bem_avaliados AS
 SELECT j.id_jogo,
    j.titulo,
    g.nome AS genero,
    d.nome AS desenvolvedora,
    j.preco,
    count(a.id_avaliacao) AS total_avaliacoes,
    round(avg(a.nota), 2) AS media_nota
   FROM (((biblioteca_jogos.jogos j
     JOIN biblioteca_jogos.generos g ON ((g.id_genero = j.id_genero)))
     JOIN biblioteca_jogos.desenvolvedoras d ON ((d.id_desenvolvedora = j.id_desenvolvedora)))
     JOIN biblioteca_jogos.avaliacoes a ON ((a.id_jogo = j.id_jogo)))
  GROUP BY j.id_jogo, j.titulo, g.nome, d.nome, j.preco
  ORDER BY (round(avg(a.nota), 2)) DESC, (count(a.id_avaliacao)) DESC;


ALTER VIEW biblioteca_jogos.vw_jeferson_jogos_bem_avaliados OWNER TO neondb_owner;

--
-- Name: vw_jeferson_usuarios_mais_ativos; Type: VIEW; Schema: biblioteca_jogos; Owner: neondb_owner
--

CREATE VIEW biblioteca_jogos.vw_jeferson_usuarios_mais_ativos AS
 SELECT u.id_usuario,
    u.nome,
    u.email,
    COALESCE(bib.total_jogos, (0)::bigint) AS jogos_na_biblioteca,
    COALESCE(bib.total_horas, (0)::numeric) AS total_horas_jogadas,
    COALESCE(av.total_avaliacoes, (0)::bigint) AS total_avaliacoes
   FROM ((biblioteca_jogos.usuarios u
     LEFT JOIN ( SELECT biblioteca.id_usuario,
            count(*) AS total_jogos,
            sum(biblioteca.horas_jogadas) AS total_horas
           FROM biblioteca_jogos.biblioteca
          GROUP BY biblioteca.id_usuario) bib ON ((bib.id_usuario = u.id_usuario)))
     LEFT JOIN ( SELECT avaliacoes.id_usuario,
            count(*) AS total_avaliacoes
           FROM biblioteca_jogos.avaliacoes
          GROUP BY avaliacoes.id_usuario) av ON ((av.id_usuario = u.id_usuario)))
  ORDER BY COALESCE(bib.total_horas, (0)::numeric) DESC NULLS LAST;


ALTER VIEW biblioteca_jogos.vw_jeferson_usuarios_mais_ativos OWNER TO neondb_owner;

